curl -s -X GET "https://www.googleapis.com/calendar/v3/users/me/calendarList" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
for cal in data.get('items', []):
    loc = cal.get('location', '')
    if loc:
        print(f\"ID: {cal['id']} | Summary: {cal.get('summary','')} | Location: {loc}\")
    else:
        print(f\"ID: {cal['id']} | Summary: {cal.get('summary','')} | Location: (none)\")
"
